n  /// A13 — manual CRM appointment marked completed.\n  APPOINTMENT_COMPLETED\n  PROPOSAL_SENT\n  CLIENT_ACQUIRED\n  NOT_INTERESTED\n  NOT_QUALIFIED\n  /// A14 — keep in DB; excluded from Active Leads / follow-up due buckets.\n  DO_NOT_CONTACT\n}\n\n/// A12 — Annual Gross Revenue classification (Reported / Estimated / Unknown).\nenum AnnualGrossRevenueKind {\n  REPORTED\n  ESTIMATED\n  UNKNOWN\n}\n\n/// A12 — Existing Sales Force (Yes / No / Unknown).\nenum ExistingSalesForce {\n  YES\n  NO\n  UNKNOWN\n}\n\n/// Append-only CRM timeline entries (author name snapshotted at write time).\nenum LeadActivityType {\n  NOTE\n  CALL\n  EMAIL\n  MEETING\n  FOLLOW_UP_SCHEDULED\n  FOLLOW_UP_COMPLETED\n  /// A13 — manual CRM appointment marked completed.\n  APPOINTMENT_COMPLETED\n  /// Master Admin assigned / reassigned the lead to a Sales Representative.\n  REASSIGNED\n}\n\n// -------------------------------------------------------------\n// AUTHENTICATED ACCOUNTS\n// AdminUser is the existing Prisma model/table name. It will temporarily store\n// all account roles so the seeded Super Admin and current relations are kept.\n// -------------------------------------------------------------\n\nmodel AdminUser {\n  id                String         @id @default(uuid()) @db.Uuid\n  name              String         @db.VarChar(120)\n  email             String         @unique @db.VarChar(255)\n  passwordHash      String?        @map(\"password_hash\")\n  /// Master-Admin credential handoff only — login still uses passwordHash.\n  adminSetPassword  String?        @map(\"admin_set_password\") @db.Text\n  role              Role           @default(USER)\n  /// Staff position for SALES_REPRESENTATIVE accounts; null for other roles.\n  position          StaffPosition? @map(\"position\")\n  isActive          Boolean        @default(true) @map(\"is_active\")\n  /// Set when access is paused; cleared on restore. Accounts are never deleted.\n  accessPauseReason String?        @map(\"access_pause